import { sql } from "drizzle-orm";
import {
  check,
  date,
  index,
  integer,
  jsonb,
  numeric,
  pgEnum,
  pgTable,
  text,
  time,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";

import type { ParsedStatement } from "@/lib/parsers/types";

import { user } from "./auth-schema";

// Auth tables (user / session / account / verification) are generated by
// Better Auth: `npx auth@1.7.7 generate --config src/lib/auth.ts
// --output src/db/auth-schema.ts`. Don't edit that file by hand.
export * from "./auth-schema";

const userIdColumn = () =>
  text("user_id").references(() => user.id, { onDelete: "cascade" });

export const categoryKind = pgEnum("category_kind", ["income", "expense"]);
export const direction = pgEnum("direction", ["in", "out"]);
export const categorySource = pgEnum("category_source", ["rule", "ai", "user"]);
export const matchType = pgEnum("match_type", ["contains", "regex"]);
export const ruleSource = pgEnum("rule_source", ["system", "user", "ai_cache"]);
export const fileType = pgEnum("file_type", ["csv", "pdf", "slip"]);
export const importStatus = pgEnum("import_status", [
  "pending", // parsed, waiting for the user to confirm the preview
  "completed",
  "failed",
]);

const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();

export const bankAccounts = pgTable(
  "bank_accounts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: userIdColumn().notNull(),
    bankCode: text("bank_code").notNull(),
    nickname: text("nickname").notNull(),
    createdAt: createdAt(),
  },
  (t) => [index("bank_accounts_user_id_idx").on(t.userId)],
);

export const categories = pgTable(
  "categories",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // null = built-in category shared by every user
    userId: userIdColumn(),
    name: text("name").notNull(),
    icon: text("icon").notNull(),
    color: text("color").notNull(),
    kind: categoryKind("kind").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    // NULLS NOT DISTINCT so built-in names (userId = null) are unique too
    unique("categories_user_id_name_unique")
      .on(t.userId, t.name)
      .nullsNotDistinct(),
  ],
);

export const imports = pgTable(
  "imports",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: userIdColumn().notNull(),
    bankAccountId: uuid("bank_account_id")
      .notNull()
      .references(() => bankAccounts.id, { onDelete: "cascade" }),
    fileName: text("file_name").notNull(),
    fileType: fileType("file_type").notNull(),
    // object key of the original file in Cloudflare R2 (Phase 7)
    storageKey: text("storage_key"),
    status: importStatus("status").notNull().default("pending"),
    // Parsed rows shown on the preview page. Only kept while pending;
    // cleared once the import is confirmed.
    preview: jsonb("preview").$type<ParsedStatement>(),
    rowCount: integer("row_count").notNull().default(0),
    duplicateCount: integer("duplicate_count").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [index("imports_user_id_created_at_idx").on(t.userId, t.createdAt)],
);

export const transactions = pgTable(
  "transactions",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: userIdColumn().notNull(),
    bankAccountId: uuid("bank_account_id")
      .notNull()
      .references(() => bankAccounts.id, { onDelete: "cascade" }),
    importId: uuid("import_id").references(() => imports.id, {
      onDelete: "set null",
    }),
    occurredAt: date("occurred_at").notNull(),
    occurredTime: time("occurred_time"),
    description: text("description").notNull(),
    merchant: text("merchant"),
    // Always positive; the sign lives in `direction`. Read as a string to
    // avoid float rounding — convert with helpers in src/lib/money.ts.
    amount: numeric("amount", { precision: 14, scale: 2 }).notNull(),
    direction: direction("direction").notNull(),
    // null categoryId = "ยังไม่จัดหมวด"
    categoryId: uuid("category_id").references(() => categories.id, {
      onDelete: "set null",
    }),
    categorySource: categorySource("category_source"),
    dedupeHash: text("dedupe_hash").notNull(),
    createdAt: createdAt(),
  },
  (t) => [
    unique("transactions_user_id_dedupe_hash_unique").on(
      t.userId,
      t.dedupeHash,
    ),
    index("transactions_user_id_occurred_at_idx").on(t.userId, t.occurredAt),
    check("transactions_amount_non_negative", sql`${t.amount} >= 0`),
  ],
);

export const categoryRules = pgTable(
  "category_rules",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // null = system rule shared by every user
    userId: userIdColumn(),
    pattern: text("pattern").notNull(),
    matchType: matchType("match_type").notNull().default("contains"),
    categoryId: uuid("category_id")
      .notNull()
      .references(() => categories.id, { onDelete: "cascade" }),
    source: ruleSource("source").notNull(),
    priority: integer("priority").notNull().default(0),
    createdAt: createdAt(),
  },
  (t) => [
    unique("category_rules_user_pattern_unique")
      .on(t.userId, t.pattern, t.matchType)
      .nullsNotDistinct(),
  ],
);

// One AI-written summary per user and month. `inputHash` fingerprints the
// numbers it was written from: the cached text is reused until the month's
// figures change (e.g. after another import).
export const monthlyInsights = pgTable(
  "monthly_insights",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: userIdColumn().notNull(),
    month: text("month").notNull(), // "YYYY-MM"
    bullets: jsonb("bullets").$type<string[]>().notNull(),
    inputHash: text("input_hash").notNull(),
    model: text("model").notNull(),
    createdAt: createdAt(),
  },
  (t) => [unique("monthly_insights_user_id_month_unique").on(t.userId, t.month)],
);

export type BankAccount = typeof bankAccounts.$inferSelect;
export type Category = typeof categories.$inferSelect;
export type NewCategory = typeof categories.$inferInsert;
export type Import = typeof imports.$inferSelect;
export type Transaction = typeof transactions.$inferSelect;
export type NewTransaction = typeof transactions.$inferInsert;
export type CategoryRule = typeof categoryRules.$inferSelect;
